/**
 * Handoff API endpoints (one-time embedded-canvas session bridge).
 */
export interface MintEmbedHandoffResponse {
    /**
     * Single-use session-bridge code; carried in the canvas URL fragment
     * (`#eh=<code>`). Absent when the session bridge could not mint one — the
     * clean `projectUrl` is still returned so the caller can degrade to it.
     */
    handoff?: string;
    /** ISO timestamp; the code expires ~60s after minting. Absent with no code. */
    expiresAt?: string;
    /** Team the code is bound to (from the API-key context). */
    teamId: string;
    /** Project the code is bound to. */
    projectId: string;
    /** Canonical, credential-free canvas URL — clean and safe to share. */
    projectUrl: string;
}
/**
 * Mint a one-time embedded-canvas handoff code bound to the API key's
 * user+team and the given project. An unattended CLI API key may mint ONLY an
 * embedded-canvas code (`kind:'embed'`): a restricted, project-scoped session
 * that reaches only the canvas view/edit surface for that one project.
 *
 * SECURITY: never log the code beyond placing it in the canvas URL fragment,
 * and never send it (or the tokenized URL) to telemetry.
 */
export declare function mintEmbedHandoff(projectId: string): Promise<MintEmbedHandoffResponse>;
